return $input.all().map(i => {
  const r = i.json;
  const pace = r.covered_pct >= r.plan_pct - 3 ? 'is on plan' : 'has a little catching up to do';
  const lines = [`Hi, this is ${r.first_name}'s week at Alcovia.`,
    `Syllabus covered: ${r.covered_pct}% (plan ${r.plan_pct}%). ${r.first_name} ${pace}.`,
    r.held ? `Sessions joined: ${r.attended} of ${r.held}.` : null,
    r.subject ? `Next exam: ${r.subject} on ${new Date(r.exam_date).toDateString()}.` : null,
    `See the full picture: https://REPLACE_APP_DOMAIN/family/${r.student_id}`].filter(Boolean);
  return { json: { phone: r.phone, text: lines.join('\n') } };
});
